from topics_a import t, T
S='solicitor'
t('solicitor',S,'a solicitor',"A solicitor gives legal advice, prepares documents, negotiates for you and, where needed, runs court cases and instructs barristers, across areas from property and family law to business and disputes.",["Choose a solicitor who specialises in your type of matter.","Ask for costs information at the start.","Check the firm on the SRA register."])
t('accident-claim-solicitor',S,'an accident claim solicitor',"Accident claim solicitors handle personal injury claims after road accidents, accidents at work and slips or trips, seeking compensation for injuries and losses.",["Most injury claims must be started within three years.","Many claims are run on a no win, no fee basis; read the terms on deductions.","Lower-value road traffic whiplash claims use the Official Injury Claim portal."])
t('agriculture-solicitor',S,'an agricultural solicitor',"Agricultural solicitors advise farmers and landowners on tenancies, land sales, succession, partnerships, rights of way and environmental schemes.",["Agricultural tenancies have special legislation.","Succession planning protects the farm.","Ask about agricultural property relief."])
t('farm-solicitor',S,'a farm solicitor',"Farm solicitors help with farm sales and purchases, family farming partnerships, tenancy disputes and planning for the next generation.",["Partnership agreements prevent disputes.","Land registration may be incomplete for older farms.","Diversification can raise planning issues."])
t('business-solicitor',S,'a business solicitor',"Business solicitors help with company formation, contracts, terms and conditions, disputes, employment and commercial property.",["Good contracts prevent costly disputes.","Shareholder agreements protect founders.","Ask about fixed-fee packages for start-ups."])
t('commercial-solicitor',S,'a commercial solicitor',"Commercial solicitors draft and negotiate contracts such as supply, distribution, agency, licensing and outsourcing agreements.",["Read limitation of liability clauses carefully.","Standard terms should match how you trade.","Disputes are cheaper to prevent than resolve."])
t('company-commercial-solicitor',S,'a company and commercial solicitor',"Company commercial solicitors combine corporate work, such as share sales and investments, with day-to-day commercial contracts.",["Due diligence protects buyers.","Investment rounds need careful documentation.","Ask about warranties and indemnities."])
t('corporate-solicitor',S,'a corporate solicitor',"Corporate solicitors advise on buying and selling companies, investment, restructures, shareholder matters and directors' duties.",["Heads of terms set the deal framework.","Disclosure letters manage warranty risk.","Directors' duties apply in hard times."])
t('commercial-property-solicitor',S,'a commercial property solicitor',"Commercial property solicitors handle leases, sales and purchases of business premises, development and landlord and tenant disputes.",["Lease terms on repair and rent review matter.","Security of tenure can be excluded.","Check service charges and dilapidations."])
t('charity-solicitor',S,'a charity solicitor',"Charity solicitors advise on setting up charities, governance, trustee duties, mergers, property and Charity Commission matters.",["Choose the right legal structure.","Trustees have personal duties.","Serious incidents must be reported."])
t('care-home-solicitor',S,'a care home solicitor',"Care home solicitors help families with care fees, contracts with homes, lasting powers of attorney and disputes about care or funding.",["Read care home contracts before signing.","NHS Continuing Healthcare may cover costs.","Deputyship may be needed without a power of attorney."])
t('civil-solicitor',S,'a civil solicitor',"Civil solicitors deal with non-criminal disputes between people and organisations, from contracts and debts to property and negligence claims.",["Pre-action protocols apply before court.","Mediation is encouraged.","Costs risks should be explained early."])
t('civil-litigation-solicitor',S,'a civil litigation solicitor',"Civil litigation solicitors take disputes through court, from letters before action to trial and enforcement.",["Limitation periods apply.","Settlement offers have costs consequences.","Ask about funding options."])
t('dispute-resolution-solicitor',S,'a dispute resolution solicitor',"Dispute resolution solicitors resolve disagreements through negotiation, mediation, arbitration or court.",["Early advice can avoid court.","Mediation is often quicker and cheaper.","Keep all correspondence."])
t('debt-recovery-solicitor',S,'a debt recovery solicitor',"Debt recovery solicitors help businesses and individuals recover money owed, from letters before action to county court claims and enforcement.",["Act before the six-year limitation period expires.","Statutory interest may apply to business debts.","Check the debtor can pay before suing."])
t('defamation-solicitor',S,'a defamation solicitor',"Defamation solicitors advise on libel and slander, including online posts and reviews, whether you are the person defamed or the one accused.",["Claims must usually be brought within one year.","Serious harm must be shown.","Act quickly to preserve evidence."])
t('clinical-negligence-solicitor',S,'a clinical negligence solicitor',"Clinical negligence solicitors pursue claims when medical treatment falls below an acceptable standard and causes harm.",["Claims usually must start within three years.","Medical records and expert evidence are key.","Many work on no win, no fee terms."])
t('criminal-solicitor',S,'a criminal solicitor',"Criminal solicitors advise and represent people at the police station and in the magistrates' and Crown Courts.",["You have the right to free legal advice at the police station.","Do not discuss the case with police before advice.","Legal aid may be available for court."])
t('criminal-defence-solicitor',S,'a criminal defence solicitor',"Criminal defence solicitors protect your rights during investigation and prosecution, prepare your defence and instruct barristers for trials.",["Contact a solicitor before any voluntary interview.","Bail conditions must be followed.","Ask about legal aid eligibility."])
t('duty-solicitor',S,'a duty solicitor',"Duty solicitors provide free legal advice at police stations and some courts to anyone who needs it, through schemes funded by legal aid.",["Police-station advice is free regardless of income.","You can ask for your own solicitor instead.","Advice can be by phone for some offences."])
t('divorce-solicitor',S,'a divorce solicitor',"Divorce solicitors guide you through no-fault divorce, financial settlements and arrangements for children, aiming for fair, lasting outcomes.",["Divorce does not end financial claims; a financial order does.","Mediation is usually required before court.","Full financial disclosure is essential."])
t('divorce-advice',S,'divorce advice',"Early divorce advice helps you understand the process, your financial position and your options for children before decisions are made.",["Separate legal and financial advice can help.","Do not move money without advice.","Consider mediation and collaborative options."])
t('family-solicitor',S,'a family solicitor',"Family solicitors handle divorce, separation, finances, children arrangements, prenuptial agreements, domestic abuse protection and adoption.",["Resolution members commit to non-confrontational approaches.","Legal aid may be available where there is domestic abuse.","Children's welfare comes first in court."])
t('child-arrangements-solicitor',S,'a child arrangements solicitor',"Child arrangements solicitors help parents agree or apply for orders about where children live and how they spend time with each parent.",["Mediation information meetings usually come first.","Courts focus on the child's welfare.","Keep communication child-focused."])
t('child-custody-solicitor',S,'a child custody solicitor',"In England and Wales, \"custody\" is now dealt with as child arrangements, and solicitors help parents settle where children live and contact with each parent.",["The legal term is child arrangements order.","Parental responsibility is separate.","Urgent protection may be available if a child is at risk."])
t('employment-solicitor',S,'an employment solicitor',"Employment solicitors advise employees and employers on dismissal, discrimination, redundancy, settlement agreements and tribunal claims.",["Tribunal claims usually require ACAS early conciliation.","Time limits are short, often three months less a day.","Settlement agreements need independent legal advice."])
t('estate-planning-solicitor','wills','an estate planning solicitor',"Estate planning solicitors combine wills, trusts, lasting powers of attorney and tax planning to protect your family and assets.",["Review plans after major life events.","Lasting powers of attorney cover health and money.","Inheritance tax rules are changing."])
t('patent-solicitor',S,'a patent lawyer',"Patent lawyers, usually patent attorneys and IP solicitors, help protect inventions, draft applications and enforce patent rights.",["Do not disclose an invention publicly before filing.","Patent attorneys are regulated by IPReg.","Searches help assess novelty."],hub='patent-attorneys')
t('conveyancer-solicitor','conveyancer','a conveyancing solicitor',"Conveyancing solicitors carry out the legal work of buying, selling and remortgaging property and can advise on wider legal issues that come up.",["Solicitors can deal with linked legal issues.","Check CQS accreditation.","Ask who handles the file."])
# barristers
B='barrister'
t('barrister',B,'a barrister',"Barristers are specialist advocates and advisers who represent clients in courts and tribunals, draft legal documents and give expert opinions.",["You may be able to instruct directly through Public Access.","Fees are usually agreed for a defined piece of work.","Choose a barrister with the right specialism."])
t('direct-access-barrister',B,'a direct access barrister',"Direct access barristers accept instructions from members of the public without a solicitor, under the Public Access scheme.",["Not every case is suitable for direct access.","You may handle some admin yourself.","Check public access registration."])
t('public-access-barrister',B,'a public access barrister',"Public access barristers are registered with the Bar Standards Board to take instructions directly from clients for suitable matters.",["The barrister will assess suitability first.","You receive a client care letter.","Fees are usually fixed per task."])
t('instruct-a-barrister',B,'how to instruct a barrister',"You can instruct a barrister through a solicitor or, for suitable matters, directly via Public Access, by sending a summary and documents to their chambers.",["Clerks manage barristers' diaries and fees.","Organise documents chronologically.","Be clear about what you need."])
t('chancery-barrister',B,'a chancery barrister',"Chancery barristers specialise in property, trusts, wills and estates, company and insolvency disputes.",["Chancery work often involves complex documents.","Inheritance disputes are common.","Mediation can resolve many cases."])
t('civil-barrister',B,'a civil barrister',"Civil barristers represent parties in non-criminal disputes, from contract and negligence claims to property and debt.",["Advice on merits helps decide whether to proceed.","Costs budgets apply in many cases.","Settlement can happen at any time."])
t('commercial-barrister',B,'a commercial barrister',"Commercial barristers handle business disputes such as contracts, shareholder disagreements, banking, insurance and arbitration.",["High-value disputes often go to the Business and Property Courts.","Arbitration is common in some sectors.","Early opinions shape strategy."])
t('criminal-barrister',B,'a criminal barrister',"Criminal barristers represent defendants (and prosecutors) in the Crown Court and magistrates' courts, from bail hearings to trials and appeals.",["Your solicitor usually instructs the barrister.","Legal aid often covers barrister fees.","Private instructions are possible."])
t('employment-barrister',B,'an employment barrister',"Employment barristers represent employees and employers in employment tribunals and advise on dismissals, discrimination and settlements.",["Tribunal deadlines are strict.","Direct access is common in employment cases.","Costs are not usually awarded in tribunals."])
t('family-barrister',B,'a family barrister',"Family barristers represent clients in divorce finances, child arrangements, care proceedings and domestic abuse cases.",["Hearings can be emotionally demanding; preparation helps.","Direct access is possible in some family cases.","Courts encourage settlement."])
t('immigration-barrister',B,'an immigration barrister',"Immigration barristers represent clients at the First-tier and Upper Tribunal and in judicial review against the Home Office.",["Appeal deadlines are short.","Evidence bundles must be organised.","Some cases are legally aided."])
t('intellectual-property-barrister',B,'an intellectual property barrister',"IP barristers advise and litigate on patents, trade marks, copyright, designs and confidential information.",["Smaller claims can use IPEC.","Evidence of ownership is key.","Act fast on infringement."])
t('personal-injury-barrister',B,'a personal injury barrister',"Personal injury barristers advise on liability and value, and represent claimants or defendants at hearings and trials.",["Barristers often advise on settlement value.","Expert evidence is crucial.","Joint settlement meetings resolve many cases."])
t('planning-barrister',B,'a planning barrister',"Planning barristers advise on planning applications, appeals, inquiries, enforcement and judicial review.",["Inquiries need careful preparation.","Judicial review deadlines are short.","Evidence from experts supports cases."])
t('public-law-barrister',B,'a public law barrister',"Public law barristers challenge decisions of public bodies through judicial review and advise on human rights and community care.",["Judicial review must be brought promptly.","Pre-action letters are required.","Funding may be available in some cases."])
t('tax-barrister',B,'a tax barrister',"Tax barristers advise on complex tax law and represent taxpayers before the tax tribunals and higher courts.",["Accountants and tax advisers can often instruct directly.","Opinions support planning decisions.","Tribunal hearings need expert preparation."])
